def _wrap(a):
    return (a + 180.) % 360. - 180.


def features(o, atk_ticks, tick):
    g = geometry_from_observation(o)
    phi, theta = math.radians(o[3]), math.radians(o[4])
    ev, ov = o[23:26], o[6:9]
    cross = _wrap(math.degrees(math.atan2(ev[1], ev[0])) - math.degrees(math.atan2(ov[1], ov[0]))) / 180.
    d_ft = g['distance_m'] / .3048
    in_band = 500. <= d_ft <= 3000.
    ba = g['blue_angle_deg']
    c = np.clip
    f = [min(g['distance_m'] / 5000., 3.), c(g['closing_mps'] / 340., -3, 3), ba / 180., g['blue_az_deg'] / 180.,
         g['blue_el_deg'] / 90., g['aspect_proxy_deg'] / 180., cross,
         math.sin(phi), math.cos(phi), math.sin(theta), math.cos(theta),
         c(o[18] / 30., -3, 3), c(o[19] / 10., -3, 3), c(o[14] / 9., -2, 2),
         o[12] / 1.6878098571011957 / 400., o[2] * .3048 / 6000.,
         c((o[22] - o[2]) * .3048 / 3000., -3, 3), float(np.linalg.norm(ev)) / 1.6878098571011957 / 400.,
         c(o[8] * .3048 / 100., -3, 3), c(o[9] / 3., -1, 1), c(o[10] / 3., -1, 1), c(o[11] / 3., -1, 1),
         atk_ticks / 180., tick / 18000., float(in_band and ba <= 1.), float(in_band), float(ba <= 5.)]
    return np.asarray(f, dtype=np.float32)


def _mask(altitude_ft):
    """same safety masking as jepa_brain.rollout.BrainPolicy / flybrain.pilot.action_mask"""
    m = np.ones(8, dtype=bool)
    agl = altitude_ft * 0.3048
    if agl < 2500:
        m[_F.LOW_YOYO] = False
    if agl < 1800:
        m[[_F.BREAK_IN, _F.BREAK_OUT, _F.HIGH_YOYO, _F.LOW_YOYO]] = False
    return m


class FlyFeatPilot(_F.ShieldedTacticalPilot):
    name = 'fly_feat'

    def __init__(self):
        super().__init__(shield=False)
        self.enable_shield(_F.TIGHT3)
        self.k = 0               # ticks flown since the round started (decision when k % 20 == 0)
        self.atk = 0             # own count of ticks in the 1-degree / 500-3000 ft envelope (approximation of the judge's counter)
        self.m = None            # EMA of the features
        self.left, self.cool, self.opt = 0, 0, _F.PURSUE
        self.n_options = 0
        self.n_errors = 0
        self.hist = [0] * 8

    def _push(self, v):
        v = np.asarray(v, np.float32)
        self.m = v.copy() if self.m is None else EMA * self.m + (1 - EMA) * v
        return np.concatenate([v, self.m])

    def _decide(self, o):
        feat = features(o, self.atk, self.k)
        x = self._push(feat)
        if self.left > 0:
            self.left -= 1
            if self.left == 0:
                self.cool = COOLDOWN
            return self.opt
        if self.cool > 0:
            self.cool -= 1
            return _F.PURSUE
        if geometry_from_observation(o)['distance_m'] >= ZONE:
            return _F.PURSUE
        a = ((x[None] - _MU) / _SD) @ _W + _B
        a = a[0]
        ok = _mask(o[2])[1:]
        a = np.where(ok, a, -1e9)
        k = int(a.argmax())
        if a[k] > TAU:
            self.opt, self.left = k + 1, HOLD - 1
            self.n_options += 1
            if self.left == 0:
                self.cool = COOLDOWN
            return self.opt
        return _F.PURSUE

    def act(self, observation, residual=None, started=True):
        if not started:
            return super().act(observation, residual, started)
        o = validate_observation(observation)
        if self.k % DECISION_TICKS == 0:
            try:
                tac = int(self._decide(o))
            except Exception:
                self.n_errors += 1
                self.left, self.cool, self.opt = 0, 0, _F.PURSUE
                tac = _F.PURSUE
            self.hist[tac] += 1
            self.set_tactic(tac)
        out = super().act(observation, residual, started)
        try:
            g = geometry_from_observation(o)
            if 500. <= g['distance_m'] / .3048 <= 3000. and g['blue_angle_deg'] <= 1.:
                self.atk += 1
        except Exception:
            pass
        self.k += 1
        return out


def build():
    return FlyFeatPilot()
